('x1', 'meb_yks_2026', 'cografya', NULL, '17 kazanım yan sütun başlığı nedeniyle tablo dışında kaldı; resmî metinden geri alındı'),
('x2', 'meb_yks_2026', 'felsefe', NULL, '4 satır başlık/bozuk kod/tekrar olarak elendi'),
('x3', 'meb_yks_2026', 'kimya', NULL, '1 satır başlık/bozuk kod/tekrar olarak elendi'),
('x4', 'meb_yks_2026', 'tarih', NULL, '2 satır başlık/bozuk kod/tekrar olarak elendi'),
('x5', 'meb_yks_2026', 'tde', NULL, 'Her sınıfın “Giriş” ünitesi ve B/C (sözlü/yazılı iletişim) kazanımları türe bağlı değil; ünite eşlemesi belgede yok, alınmadı'),
('x6', 'meb_yks_2026', 'tde', NULL, '5 kazanım “Bu kazanım 10, 11 ve 12. sınıf düzeylerinde ele alınacaktır” notu nedeniyle 9. sınıf ünitelerinden çıkarıldı'),
('x7', 'meb_yks_2026', 'tde', NULL, 'Kazanım kodları belgede sınıf içermez (A.2.1 …); ayırt etmek için sınıf.ünite öneki eklendi (ör. 9.2/A.2.1). A.4 bilgilendirici metin ünitelerine eşleme ünite türünden çıkarıldı'),
('x8', 'meb_yks_2026', 'felsefe-grubu', NULL, '8 bozuk/yarım açıklama parçası (PDF yazı tipi kodlaması) alınmadı; Mantık 7, Psikoloji 8 açıklama satırı metne çıkarılamadı'),
